mapper.select:
SELECT /* org.bplte.core.api.domain.comment.mapper.CommentReactionMapper.selectCommentReactionEntityList */ REACTION_ID AS reactionId , COMMENT_ID AS commentId , USER_ID AS userId , REACTION_TYPE AS reactionType , REG_DT AS regDt , RGTR_ID AS rgtrId , MDFCN_DT AS mdfcnDt , MDFR_ID AS mdfrId FROM TBL_COMMENT_REACTION WHERE COMMENT_ID = #{commentId}
AND USER_ID = #{userId}
ORDER BY REG_DT ASC

mapper.insert:
INSERT INTO TBL_COMMENT_REACTION ( /* org.bplte.core.api.domain.comment.mapper.CommentReactionMapper.insertCommentReaction */
      COMMENT_ID
    , USER_ID
    , REACTION_TYPE
    , REG_DT
    , RGTR_ID
    , MDFCN_DT
    , MDFR_ID
) VALUES (
      #{commentId}
    , #{userId}
    , #{reactionType}
    , NOW()
    , #{rgtrId}
    , NOW()
    , #{mdfrId}
)

mapper.update:
UPDATE TBL_COMMENT_REACTION /* org.bplte.core.api.domain.comment.mapper.CommentReactionMapper.updateCommentReaction */
SET REACTION_TYPE = #{reactionType}, MDFR_ID = #{mdfrId}, MDFCN_DT = NOW()
WHERE REACTION_ID = #{reactionId}
